#include "test_common.h"
#include "darc_internal.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <dirent.h>
#include <sys/stat.h>
#include <limits.h>

static TestProc si(const char*r){const char*a[]={"./darc","init",r,NULL};return test_exec(a,NULL);}
static TestProc ss(const char*r,const char*s,const char*const env[]){const char*a[]={"./darc","--repo",r,"snapshot","create",s,"--timestamp","7000",NULL};return test_exec(a,env);}
static TestProc sv(const char*r,const char*const env[]){const char*a[]={"./darc","--repo",r,"verify","--level","full",NULL};return test_exec(a,env);}
static TestProc sr(const char*r,const char*to,const char*const env[]){const char*a[]={"./darc","--repo",r,"restore","HEAD","--to",to,NULL};return test_exec(a,env);}
static bool store_obj(const char*r,uint8_t type,const uint8_t*p,size_t n,DarcCid*out){DarcConfig c;darc_config_defaults(&c);c.compression_enabled=false;bool nn;uint64_t sb;int rc=darc_object_store(r,type,p,n,&c,out,&sb,&nn);darc_config_free(&c);return rc==0;}
static bool publish_snap(const char*r,const DarcCid*root,uint64_t files,uint64_t dirs,uint64_t logical,DarcCid*out){DarcSnapshotObj s;memset(&s,0,sizeof s);s.created_ns=1;s.root=*root;s.root_mode=0755;s.logical_bytes=logical;s.files=files;s.dirs=dirs;DarcBuf b;if(darc_snapshot_serialize(&s,&b))return false;bool ok=store_obj(r,OBJ_SNAPSHOT,b.data,b.len,out);darc_buf_free(&b);if(!ok)return false;char h[65],rel[128],line[66];darc_cid_hex(out,h);snprintf(rel,sizeof rel,"refs/snapshots/%s",h);snprintf(line,sizeof line,"%s\n",h);char*p=test_path(r,rel),*head=test_path(r,"HEAD");ok=p&&head&&!test_write(p,line,65,0644)&&!test_write(head,line,65,0644)&&!darc_index_rebuild(r);free(p);free(head);return ok;}
static bool make_file_obj(const char*r,const uint8_t*data,size_t n,DarcCid*out){DarcCid cc;if(!store_obj(r,OBJ_CHUNK,data,n,&cc))return false;DarcFileObj f;memset(&f,0,sizeof f);f.logical_size=n;f.chunk_n=1;f.chunks=calloc(1,sizeof* f.chunks);if(!f.chunks)return false;f.chunks[0].cid=cc;f.chunks[0].len=n;darc_sha256(data,n,f.digest);DarcBuf b;bool ok=!darc_file_serialize(&f,&b)&&store_obj(r,OBJ_FILE,b.data,b.len,out);darc_buf_free(&b);darc_file_free(&f);return ok;}
static bool write_malformed_frame(const char*r,const DarcCid*c,uint8_t codec,uint64_t ul,uint64_t sl,const uint8_t*p,size_t pn){char*fp=darc_object_path(r,c);if(!fp)return false;char*dir=darc_dirname_dup(fp);bool ok=dir&&!darc_mkdir_p(dir,0755);free(dir);DarcBuf b;darc_buf_init(&b);if(ok)ok=!darc_buf_put(&b,"DARCOBJ1",8)&&!darc_buf_u8(&b,OBJ_CHUNK)&&!darc_buf_u8(&b,codec)&&!darc_buf_u16(&b,0)&&!darc_buf_u64(&b,ul)&&!darc_buf_u64(&b,sl)&&!darc_buf_u32(&b,darc_crc32c(b.data+8,20))&&!darc_buf_put(&b,p,pn)&&!darc_buf_u32(&b,darc_crc32c(p,pn))&&!test_write(fp,b.data,b.len,0644);darc_buf_free(&b);free(fp);return ok;}
static bool flip_chunk_for_path(const char*r,const char*path,DarcCid*out){DarcCid sid;DarcSnapshotObj s={0};DarcFlatTree t={0};if(darc_resolve_snapshot(r,"HEAD",&sid,&s)||darc_flatten_snapshot(r,&s,&t)){darc_snapshot_free(&s);return false;}DarcFlatEnt*e=darc_flat_find(&t,path);bool ok=false;if(e&&e->type==1){DarcObject o;DarcFileObj f={0};if(!darc_object_load(r,&e->cid,&o,1)&&!darc_file_parse(o.payload.data,o.payload.len,&f)&&f.chunk_n){*out=f.chunks[0].cid;char*p=darc_object_path(r,out);int fd=p?open(p,O_RDWR|O_CLOEXEC):-1;uint8_t z;if(fd>=0&&pread(fd,&z,1,32)==1){z^=0x80;ok=pwrite(fd,&z,1,32)==1;}if(fd>=0)close(fd);free(p);darc_file_free(&f);darc_object_free(&o);}}darc_flat_free(&t);darc_snapshot_free(&s);return ok;}

void test_security(void){
 TestProc x;
 /* SEC-001: malicious ../sentinel through a TREE named '..'. */
 {char*d=test_case_dir("sec001"),*r=test_path(d,"repo"),*out=test_path(d,"out"),*sent=test_path(d,"sentinel");x=si(r);test_proc_free(&x);DarcCid fc,child,root,sid;bool ok=make_file_obj(r,(const uint8_t*)"PWN",3,&fc);DarcTreeEnt ce;memset(&ce,0,sizeof ce);ce.name=(uint8_t*)"sentinel";ce.name_len=8;ce.type=1;ce.mode=0644;ce.cid=fc;DarcTreeObj ct={&ce,1};DarcBuf cb;if(ok)ok=!darc_tree_serialize(&ct,&cb)&&store_obj(r,OBJ_TREE,cb.data,cb.len,&child);darc_buf_free(&cb);DarcTreeEnt re;memset(&re,0,sizeof re);re.name=(uint8_t*)"..";re.name_len=2;re.type=2;re.mode=0755;re.cid=child;DarcTreeObj rt={&re,1};DarcBuf rb;if(ok)ok=!darc_tree_serialize(&rt,&rb)&&store_obj(r,OBJ_TREE,rb.data,rb.len,&root);darc_buf_free(&rb);if(ok)ok=publish_snap(r,&root,1,1,3,&sid);test_write(sent,"SAFE",4,0644);x=sr(r,out,NULL);DarcBuf z={0};bool safe=!test_read(sent,&z)&&z.len==4&&!memcmp(z.data,"SAFE",4);test_check("SEC-001",ok&&x.code!=0&&safe,"malicious '..' manifest cannot escape restore root; outside sentinel unchanged");darc_buf_free(&z);test_proc_free(&x);free(sent);free(out);free(r);free(d);}
 /* SEC-002: destination symlink parent exists before restore. */
 {char*d=test_case_dir("sec002"),*r=test_path(d,"repo"),*s=test_path(d,"src"),*sub=test_path(s,"sub"),*p=test_path(sub,"x"),*to=test_path(d,"to"),*outside=test_path(d,"outside");test_mkdir(sub);test_write(p,"x",1,0644);x=si(r);test_proc_free(&x);x=ss(r,s,NULL);test_proc_free(&x);test_mkdir(to);test_mkdir(outside);char*linkp=test_path(to,"src");symlink(outside,linkp);x=sr(r,to,NULL);char*escaped=test_path(outside,"sub/x");test_check("SEC-002",x.code==8&&access(escaped,F_OK)!=0,"pre-existing symlink parent is rejected by component-wise restore");test_proc_free(&x);free(escaped);free(linkp);free(outside);free(to);free(p);free(sub);free(s);free(r);free(d);}
 /* SEC-003: huge stored length is rejected before size/allocation overflow. */
 {char*d=test_case_dir("sec003"),*r=test_path(d,"repo");x=si(r);test_proc_free(&x);DarcCid c;darc_object_cid(OBJ_CHUNK,"x",1,&c);uint8_t dummy=0;bool ok=write_malformed_frame(r,&c,0,UINT64_MAX-1,UINT64_MAX-1,&dummy,0);darc_index_rebuild(r);x=sv(r,NULL);test_check("SEC-003",ok&&x.code==6,"near-u64 framed length rejected without attempting enormous allocation");test_proc_free(&x);free(r);free(d);}
 /* SEC-004: valid LZH1 stream whose declared output is too small. */
 {char*d=test_case_dir("sec004"),*r=test_path(d,"repo");x=si(r);test_proc_free(&x);DarcBuf lz;bool ok=!darc_lzh1_compress((const uint8_t*)"abc",3,&lz);DarcCid c;darc_object_cid(OBJ_CHUNK,"abc",3,&c);if(ok)ok=write_malformed_frame(r,&c,1,2,(uint64_t)lz.len,lz.data,lz.len);darc_buf_free(&lz);darc_index_rebuild(r);x=sv(r,NULL);test_check("SEC-004",ok&&x.code==6,"compressed stream that would overrun declared semantic length is rejected");test_proc_free(&x);free(r);free(d);}
 /* SEC-005: NUL inside TREE component is repository corruption. */
 {char*d=test_case_dir("sec005"),*r=test_path(d,"repo"),*to=test_path(d,"to");x=si(r);test_proc_free(&x);DarcCid fc,tc,sid;bool ok=make_file_obj(r,(const uint8_t*)"x",1,&fc);DarcBuf b;darc_buf_init(&b);uint8_t nm[3]={'a',0,'b'};if(ok)ok=!darc_buf_u16(&b,1)&&!darc_buf_u64(&b,1)&&!darc_buf_u64(&b,3)&&!darc_buf_put(&b,nm,3)&&!darc_buf_u8(&b,1)&&!darc_buf_u32(&b,0644)&&!darc_buf_i64(&b,0)&&!darc_buf_put(&b,fc.b,32)&&!darc_buf_u64(&b,0)&&store_obj(r,OBJ_TREE,b.data,b.len,&tc);darc_buf_free(&b);if(ok)ok=publish_snap(r,&tc,1,0,1,&sid);x=sv(r,NULL);TestProc y=sr(r,to,NULL);test_check("SEC-005",ok&&x.code==6&&y.code!=0,"semantic path containing embedded NUL is rejected as repository/path corruption");test_proc_free(&x);test_proc_free(&y);free(to);free(r);free(d);}
 /* SEC-006: PATH trap tools must never be delegated to. */
 {char*d=test_case_dir("sec006"),*bin=test_path(d,"bin"),*log=test_path(d,"trap.log"),*r=test_path(d,"repo"),*s=test_path(d,"src"),*p=test_path(s,"a"),*to=test_path(d,"out");test_mkdir(bin);test_mkdir(s);test_write(p,"abc",3,0644);const char*names[]={"tar","find","sha256sum","gzip","sort","cp","mv",NULL};for(int i=0;names[i];i++){char*q=test_path(bin,names[i]);char body[1024];snprintf(body,sizeof body,"#!/bin/sh\necho %s >> '%s'\nexit 88\n",names[i],log);test_write(q,body,strlen(body),0755);chmod(q,0755);free(q);}char envbuf[PATH_MAX+32];snprintf(envbuf,sizeof envbuf,"PATH=%s",bin);const char*env[]={envbuf,NULL};x=si(r);bool ok=x.code==0;test_proc_free(&x);x=ss(r,s,env);ok&=x.code==0;test_proc_free(&x);x=sv(r,env);ok&=x.code==0;test_proc_free(&x);x=sr(r,to,env);ok&=x.code==0;test_proc_free(&x);test_check("SEC-006",ok&&access(log,F_OK)!=0,"core workflows do not shell/delegate to tar/find/hash/compression utilities");free(to);free(p);free(s);free(r);free(log);free(bin);free(d);}
 /* SEC-007: repository nested under source never archives itself recursively. */
 {char*d=test_case_dir("sec007"),*s=test_path(d,"src"),*r=test_path(s,"repo"),*p=test_path(s,"a");test_mkdir(s);test_write(p,"payload",7,0644);x=si(r);test_proc_free(&x);bool ok=true;for(int i=0;i<4;i++){x=ss(r,s,NULL);ok&=x.code==0;test_proc_free(&x);}const char*a[]={"./darc","--repo",r,"snapshot","show","HEAD","--format","json",NULL};/* format is command-global, use canonical form below */const char*b[]={"./darc","--repo",r,"--format","json","snapshot","show","HEAD",NULL};(void)a;x=test_exec(b,NULL);ok&=x.code==0&&test_contains(x.out,"\"files\":1");test_check("SEC-007",ok,"repo-under-source boundary is skipped across repeated snapshots; archived file count stays stable");test_proc_free(&x);free(p);free(r);free(s);free(d);}
 /* SEC-008: weird control-byte path cannot inject raw path into integrity diagnostics. */
 {char*d=test_case_dir("sec008"),*r=test_path(d,"repo"),*s=test_path(d,"src");test_mkdir(s);char weird[]="bad\n\tname";char*p=test_path(s,weird);test_write(p,"payload",7,0644);x=si(r);test_proc_free(&x);x=ss(r,s,NULL);test_proc_free(&x);char path[64];snprintf(path,sizeof path,"src/%s",weird);DarcCid cc;bool m=flip_chunk_for_path(r,path,&cc);char h[65];darc_cid_hex(&cc,h);x=sv(r,NULL);test_check("SEC-008",m&&x.code==6&&test_contains(x.err,h)&&!test_contains(x.err,"bad\n"),"integrity error remains line-structured and CID-based for control-character filenames");test_proc_free(&x);free(p);free(s);free(r);free(d);}
}
